"""README.md text of the corpus (deterministic; generated by gen.py)."""
from collections import Counter

FAMILY_TEXT = [
    ("E", "event, config, command, machine-bytes and rectangle validation (error codes)"),
    ("I", "gesture transcripts: click, drag, wheel, pinch, long press, lasso, double click"),
    ("V", "keyboard navigation, key actions, the spatial metric, the reveal rule, caps"),
    ("L", "the corner-node marquee"),
    ("B", "key tokens and bindings"),
    ("C", "companion trees, windows, live text"),
    ("P", "DOM plans (full build and update) and the invariant I-C1"),
    ("Q", "executor logs over the recording DOM"),
    ("G", "accessibility gate reports (single-fault rows over three base rows)"),
    ("X", "export bundle, PNG binding chunk, manifest and bundle verification"),
    ("M", "composed capability manifests"),
    ("H", "headless outputs and argument errors"),
    ("D", "differential tier (runtime, seeds from the caller; empty cells)"),
    ("K", "mutants (test code; empty cells)"),
]

DIRS = [
    ("scenes/, layouts/", "authored IGS/1 scenes and `igl-fixed/1` layouts (canonical bytes, no trailing newline); `O1` and `layouts/O1.layout.json` are the frozen bytes; `layouts/O1.alt.layout.json` is the `O1alt` layout"),
    ("states/", "canonical IGR-CJ/1 state bytes (inputs of I, V, L, C, G, X rows)"),
    ("scripts/, transcripts/", "I, V, L scripts (ordinary JSON) and their expected `{final_state, steps}` results (IGR-CJ/1)"),
    ("inputs/", "key list, binding tables, machine bytes, the A.4 event file"),
    ("trees/, plans/, logs/", "companion trees (IGR-CJ/1), DOM plans and executor logs (LF-terminated lines, split on U+000A only)"),
    ("gates/", "gate reports (IGR-CJ/1)"),
    ("json/, manifests/, png/", "token list, default bindings, export manifests, composed manifests, binding results, PNG fixtures"),
    ("data/", "`O1.svg` (3,193 bytes, no declaration), `O1.decl.svg` (3,232 bytes), `O1.dl`: the oracle's own `igr-svg/1` and `igr-dl/1` bytes for `O1`"),
    ("headless/", "outputs of the H rows"),
    ("generated/", "`GENERATED.tsv` (id, role, path, bytes, sha256 of the one generated vector, `X24`) and its recipe"),
    ("APPENDIX-A.tsv, MUTANTS.tsv, PARITY.tsv", "generated reports (below)"),
]


def _numkey(s):
    digits = "".join(c for c in s[1:] if c.isdigit())
    return (s[0], int(digits), s)


def render(rows, rep, mm, parity):
    cnt = Counter(r.group for r in rows.values())
    withc = Counter(r.group for r in rows.values() if r.group not in "DK")
    L = []
    A = L.append
    A("# IGR-IA/1 oracle corpus (`oracles-ia`)\n")
    A("Status: **DRAFT** (not frozen; no digest of `SHA256SUMS` is pinned anywhere; the third-party `verifyScene` / `verifyLayout` / `bindLayout` / `parseState` run over the authored")
    A("`scenes/`, `layouts/`, `states/` files, required by design 32 15.1, has not been done). Produced against design 32 (`32-INTERACTION-A11Y-EXPORT-DESIGN.md`, written against **rev 2**, refreshed against **rev 3**: rev 3 changes no expected file, `EXPECT.tsv` row or input file) by an oracle author who")
    A("was given only that design, designs 27 (rev 5), 30 (rev 4) and 31 (rev 5), `docs/specs/IGS-1.md`, `docs/specs/IGL-1.md`, `docs/conformance/README.md`, the frozen fixtures")
    A("(`fixtures/oracles`, `fixtures/oracles-igl`) and the file-format conventions (README, `EXPECT.tsv`, `SHA256SUMS`, `generated/GENERATED.tsv`) of the other corpora.")
    A("Read `AMBIGUITIES.md` before judging any mismatch: it lists 70 places where the design was ambiguous, contradictory or could not be built, with the reading used.\n")
    A("## Independence statement\n")
    A("* Every expected byte comes from the Python code in `tools/` (standard library only, Python 3.12: `hashlib`, `json`, `math`, `re`, `struct`, `zlib`, `os`, `shutil`). `tools/base.py`")
    A("  (canonical JSON, integer math, scene/layout writers, model, state, texts), `tools/machine.py` (events, key tokens, bindings, machine, navigation, lasso, reveal),")
    A("  `tools/companion.py` (tree, live text, plan, executor, simulated DOM, gate), `tools/export.py` (the oracle's **own** `igr-svg/1` and `igr-dl/1` writers re-implemented from designs 30 and 31,")
    A("  PNG container, export manifest, bundle verification, manifest composition, headless), `tools/rows_a.py` and `tools/rows_b.py` (the rows), `tools/corpus.py` (scene registry, helpers),")
    A("  `tools/appendix_a.py` (extraction of the Appendix A blocks from the design file), `tools/parity.py`, `tools/readme.py`, `tools/gen.py` (driver, self-checks, mutant matrix, `SHA256SUMS`).")
    A("* The author did **not** read, import, copy or run any TypeScript, anything under `packages/`, any `reviews/*.md` or author-notes file, or any tool code of another corpus.")
    A("  Tracked expected files of `fixtures/oracles-svg` and `fixtures/oracles-dl` (and their `EXPECT.tsv`) were read **only** by `tools/parity.py` to produce `PARITY.tsv`; no byte is copied from them and nothing in this corpus refers to another corpus.")
    A("* Self-contained: `scenes/O1.scene.json` and `layouts/O1.layout.json` are byte copies of the frozen `igs:O1` and `igl:F01` files (digests asserted at generation time:")
    A("  scene `e8a4357a01a4f47f46a18b8f1c22c15a9f8c26cb06ed6b31588cd5c11407a1dc`, layout `2f37ccf2d351dc8e6b742b5b4d7fe87fc182226a2ba2cf02ffbf832af66b23db`). Every other scene, layout and state is")
    A("  authored here (source hash 64 `0`), checked only by the generator's light checker (canonical form, ordering, hashes). **A third party must run `verifyScene`, `verifyLayout`, `bindLayout`")
    A("  over every file of `scenes/` and `layouts/` and `parseState` over every file of `states/`** (design 15.1) before the corpus leaves DRAFT.")
    A("* Shared assumption: oracle and code implement the same written rules; the corpus proves agreement with the text as read in `AMBIGUITIES.md`, not that a rule is wise (design R-1).\n")
    A("## Regeneration\n")
    A("```sh")
    A("python tools/gen.py                # rebuilds every generated file (all but tools/ and AMBIGUITIES.md); deterministic, any PYTHONHASHSEED")
    A("python tools/gen.py --mutant K05   # prints, for the named mutant, which of its killer rows change")
    A("```\n")
    A("`gen.py` wipes the generated directories first, so it regenerates from empty. It builds all rows, writes the files, runs the self-checks (every tree and state file canonical; every")
    A("tree item equals the oracle's own accessible model; invariant I-C1 for `P02`, `P04`, `P07`, `P08` on a simulated DOM; no path leaves the corpus), reproduces Appendix A (`APPENDIX-A.tsv`),")
    A("runs the mutant matrix (`MUTANTS.tsv`), the parity check (`PARITY.tsv`), writes this README and finally `SHA256SUMS` (one line `<sha256> *<path>` per file except `tools/` and itself, sorted by byte order of the path).")
    A("Verify with `sha256sum -c SHA256SUMS` from this directory. The digest of `SHA256SUMS` itself is not stored here (this README is covered by it).\n")
    A("## Layout\n")
    A("`EXPECT.tsv`: header `id group tier scene layout input expected error`, one row per id (**%d rows**), `group` the leading letter, `tier` `core` except `D` (`diff`) and `K` (empty); `scene`, `layout` paths relative to this" % len(rows))
    A("directory (never leaving it) or empty; `input` a relative path or inline JSON (starts with `{` or `[`); `expected` a path or empty; `error` empty or `CODE/REASON`. One row = one scene, one layout, one input.\n")
    A("| Directory | Content |\n|---|---|")
    for d, t in DIRS:
        A("| `%s` | %s |" % (d, t))
    A("")
    A("## Families and tiers\n")
    A("| Family | Rows | With files or inline input | Content |\n|---|---|---|---|")
    for f, t in FAMILY_TEXT:
        A("| %s | %d | %d | %s |" % (f, cnt[f], withc[f], t))
    A("| **total** | **%d** | **%d** | |" % (sum(cnt.values()), sum(withc.values())))
    A("")
    A("Tier `core` is every row of E, I, V, L, B, C, P, Q, G, X, M, H (byte equality against the written rules, level IA0); `diff` (D) is a runtime tier of the test suite; K rows are mutants in test code.")
    A("Rows with an `error` and no expected file: " + ", ".join(sorted((r.id for r in rows.values() if r.error), key=_numkey)) + ".\n")
    A("## Appendix A reproduction (`APPENDIX-A.tsv`)\n")
    A("Blocks are extracted from the design file by rules X1 to X3 (split on LF, final LF added to `lines,` blocks, hex unhexed); the quoted size and SHA-256 are compared with the quoted block and with the generator's bytes.\n")
    A("| Item | Kind | Quoted bytes | Generated bytes | Status |\n|---|---|---|---|---|")
    for r in rep:
        A("| %s | %s | %s | %s | %s |" % (r[0], r[1], r[3] if r[3] else "", r[5] if r[5] else "", r[7]))
    A("")
    A("## Parity of the oracle's own SVG and display-list writers (`PARITY.tsv`)\n")
    A("The corpus does not copy `oracles-svg` / `oracles-dl` bytes. At generation time the oracle's writers are run on the frozen-fixture rows `G01`-`G10` of both corpora (initial state, default options) and on `svg:O05`")
    A("and compared with the tracked expected files (read-only): **%d of %d MATCH**.\n" % (sum(1 for p in parity if p[-1] == "MATCH"), len(parity)))
    A("| Row | Status | SHA-256 (this writer) |\n|---|---|---|")
    for p in parity:
        A("| %s | %s | `%s` |" % (p[0], p[5], p[2]))
    A("")
    A("## Mutants (`MUTANTS.tsv`)\n")
    vc = Counter(r[1] for r in mm)
    A("The 128 mutants of design 15.6 are switchable variants inside the Python reference (`--mutant Knn`; the switch set is `MUT` in `tools/base.py`). For each mutant the named killer rows are re-evaluated **on the stored")
    A("baseline inputs** with the mutant active and the output (expected files and error code) is compared with the baseline: " + ", ".join("%s %d" % (k, v) for k, v in sorted(vc.items())) + ".")
    A("`K84` is JavaScript-only (a plain object keyed by graph strings) and is recorded `not-applicable`; its killers `C16`, `I51` exist. A crash is never counted as a kill (the one structured-versus-unstructured")
    A("difference the design asks for, `K112` on `X25`, is a recorded `UNSTRUCTURED/RecursionError` result).\n")
    A("| Mutant | Verdict | Named killer rows | Rows that changed |\n|---|---|---|---|")
    for r in mm:
        A("| %s | %s | %s | %s |" % (r[0], r[1], r[2], r[3]))
    A("")
    A("## Rows that claim no bytes, and items outside the oracle (design 15.3, 15.7)\n")
    acc = sorted((r.id for r in rows.values() if r.group not in "DK" and not r.expected and not r.error), key=_numkey)
    A("**Accepted rows** (`expected` and `error` both empty) claim only that the function returns without error and claim **no bytes**: " + ", ".join(acc) + " (%d rows)." % len(acc))
    A("Error rows (`error` set, `expected` empty) claim the error code only. An empty plan (`P03`) is a zero-byte file named in `expected`.\n")
    A("Tested only in the TypeScript tranche, with **no oracle bytes and no row that claims any** (cannot be built in Python, `AMBIGUITIES.md` A-60 to A-64): the binder, `mountCompanion`, adapter focus restoration and `COMPANION_CSS`;")
    A("`verifyCompanionTree`, `maxTreeBytes`, the executor guards (the simulated DOM here has them, `gen.py` self-checks them, no row asserts them) and the `INVALID_TREE/INCONSISTENT` planner assertion; properties I1-I5, I-C1 on random inputs and tier D;")
    A("the `2^31` omission of the reveal; the TypeScript mutation `K84` (`not-applicable` here; `C16`, `I51` carry bytes); the reducer part of `H05` (an error row, no bytes). Nothing in `EXPECT.tsv` names these items except the rows just mentioned.\n")
    A("## Notes\n")
    A("* `X24` is an oversize input recorded as a generated vector (`generated/GENERATED.tsv`): 1,048,577 bytes of 0x41, one over the 1,048,576-byte manifest limit.")
    A("* No row needed a search-built input; no seeded search is recorded. Tier D has no files by design.")
    A("* Expected files are never regenerated to make code pass; additions take new ids (design 0.12).")
    return "\n".join(L) + "\n"
